export const tasksForHist=k=>histTasks[k];
export const validHist=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];
export const advanceHist=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;
export const numericHist=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;
